const $=id=>document.getElementById(id);let mode='image',items=[],selected=0,ratio='original',quality='256',history=[],future=[],playing=false,playStart=0,worker=null,cancelled=false,busy=false,resultURL='',videoURL='',vidDuration=0,frameIndex=0,toastTimer,dirty=false;
const ids=['width','height','lock','fit','delay','speed','fps','loop','loopCount','direction','target','bg','transparent','zoom','posX','posY','rotation','flip','firstHold','lastHold','filename','start','end'];
const num=(id,fallback=0)=>Number.isFinite(+$ (id).value)?+$ (id).value:fallback;
const bounded=(id,min,max)=>Math.min(max,Math.max(min,num(id,min)));
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4000)}
function snapshot(){return {items:items.map(x=>({...x})),selected,ratio,quality,values:Object.fromEntries(ids.map(id=>[id,$(id).type==='checkbox'?$(id).checked:$(id).value]))}}
