$('undo').onclick=()=>{future.push(snapshot());restore(history.pop())};$('redo').onclick=()=>{history.push(snapshot());restore(future.pop())};
function dimensions(){return [Math.round(bounded('width',16,1920)),Math.round(bounded('height',16,1920))]}
