function repeats(){return $('loop').value==='custom'?Math.round(bounded('loopCount',2,100)):num('loop')}
function update(){const [w,h]=dimensions();$('summary').innerHTML=`${w} × ${h} px <span>${total()?total().toFixed(2)+' 秒 · ':''}${mode==='image'?items.length+' 张图片':vidDuration?'视频片段':'准备好后即可导出'}</span>`;$('loopCountLabel').hidden=$('loop').value!=='custom';document.querySelectorAll('[data-ratio]').forEach(b=>b.classList.toggle('selected',b.dataset.ratio===ratio));document.querySelectorAll('[data-quality]').forEach(b=>b.classList.toggle('selected',b.dataset.quality===quality));$('count').textContent=items.length;buttons();draw();}
function drawSource(ctx,source,w,h){ctx.clearRect(0,0,w,h);if(!$('transparent').checked){ctx.fillStyle=$('bg').value;ctx.fillRect(0,0,w,h)}const sw=source.videoWidth||source.naturalWidth||source.width,sh=source.videoHeight||source.naturalHeight||source.height;if(!sw||!sh)return;const angle=num('rotation')*Math.PI/180,swap=num('rotation')%180!==0,rw=swap?sh:sw,rh=swap?sw:sh,fit=$('fit').value,z=num('zoom',1);let dw,dh;if(fit==='stretch'){dw=(swap?h:w)*z;dh=(swap?w:h)*z}else{const s=(fit==='cover'?Math.max(w/rw,h/rh):Math.min(w/rw,h/rh))*z;dw=sw*s;dh=sh*s}const bw=swap?dh:dw,bh=swap?dw:dh,x=(w-bw)*num('posX')/100+bw/2,y=(h-bh)*num('posY')/100+bh/2;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale($('flip').value==='x'?-1:1,$('flip').value==='y'?-1:1);ctx.drawImage(source,-dw/2,-dh/2,dw,dh);ctx.restore()}
function draw(){const source=mode==='image'?items[selected]?.image:vidDuration?$('video'):null;$('empty').hidden=!!source;$('preview').hidden=!source;$('stagebadge').hidden=!source;if(!source)return;const [w,h]=dimensions(),scale=Math.min(1,960/w,960/h);$('preview').width=Math.round(w*scale);$('preview').height=Math.round(h*scale);drawSource($('preview').getContext('2d'),source,$('preview').width,$('preview').height);$('previewinfo').textContent=mode==='image'?`${Math.min(selected+1,items.length)} / ${items.length} · ${total().toFixed(2)} 秒`:`${$('video').currentTime.toFixed(1)} 秒 / ${vidDuration.toFixed(1)} 秒`;}
function move(i,j){if(j<0||j>=items.length)return;const [item]=items.splice(i,1);items.splice(j,0,item);selected=j;record();renderFrames();update()}
function renderFrames(){$('frames').replaceChildren();if(!items.length){const p=document.createElement('p');p.className='muted';p.textContent='添加图片后，可拖动缩略图调整顺序。';$('frames').append(p)}items.forEach((it,i)=>{const card=document.createElement('div');card.className='frame'+(selected===i?' selected':'');card.draggable=true;const img=new Image();img.src=it.url;img.alt=it.name;img.onclick=()=>{selected=i;stop();renderFrames();draw()};card.append(img);const foot=document.createElement('div');foot.className='framefoot';const n=document.createElement('span');n.textContent=String(i+1).padStart(2,'0');const input=document.createElement('input');input.type='number';input.min='.02';input.max='60';input.step='.1';input.value=it.delay;input.title='停留秒数';input.setAttribute('aria-label',`第 ${i+1} 张图片停留秒数`);input.onchange=()=>{it.delay=Math.min(60,Math.max(.02,Number(input.value)||1));input.value=it.delay;record();update()};foot.append(n,input);card.append(foot);const actions=document.createElement('div');actions.className='framebuttons';[['←','向前移动',()=>move(i,i-1)],['→','向后移动',()=>move(i,i+1)],['×','删除图片',()=>{items.splice(i,1);selected=Math.max(0,Math.min(selected,items.length-1));record();renderFrames();update()}]].forEach(([text,label,fn])=>{const b=document.createElement('button');b.textContent=text;b.setAttribute('aria-label',label);b.onclick=fn;actions.append(b)});card.append(actions);card.ondragstart=e=>e.dataTransfer.setData('text/plain',i);card.ondragover=e=>e.preventDefault();card.ondrop=e=>{e.preventDefault();e.stopPropagation();const v=e.dataTransfer.getData('text/plain');if(v!=='')move(Number(v),i)};$('frames').append(card)})}
function stop(){playing=false;$('play').textContent='▶';$('play').setAttribute('aria-label','播放预览');$('video').pause()}
function switchMode(next){if(busy)return;stop();mode=next;$('imageTab').classList.toggle('active',mode==='image');$('videoTab').classList.toggle('active',mode==='video');$('imageTab').setAttribute('aria-selected',mode==='image');$('videoTab').setAttribute('aria-selected',mode==='video');for(const id of ['frames','reverse','imageTiming'])$(id).hidden=mode!=='image';for(const id of ['videoControls','videoTiming'])$(id).hidden=mode!=='video';$('materialTitle').firstChild.textContent=mode==='image'?'图片序列 ':'视频片段 ';$('count').hidden=mode!=='image';$('choose').textContent=mode==='image'?'选择图片':'选择视频';$('add').textContent=mode==='image'?'＋ 添加图片':'更换视频';$('uploadHint').textContent=mode==='image'?'拖入多张图片，或从设备中选择。':'拖入一段视频，截取你喜欢的片刻。';$('formats').textContent=mode==='image'?'JPG、PNG、WebP · 支持多选':'MP4、WebM · 取决于浏览器解码支持';$('fileInput').accept=mode==='image'?'image/jpeg,image/png,image/webp':'video/*';$('fileInput').multiple=mode==='image';update()}
$('imageTab').onclick=()=>switchMode('image');$('videoTab').onclick=()=>switchMode('video');for(const id of ['choose','add'])$(id).onclick=()=>$('fileInput').click();
async function loadFiles(files){if(busy)return;stop();const list=Array.from(files);if(mode==='image'){let added=0;for(const f of list){if(!/^image\/(jpeg|png|webp)$/.test(f.type)){toast('仅支持 JPG、PNG、WebP 图片');continue}if(items.length>=100){toast('单个项目最多添加 100 张图片');break}const url=URL.createObjectURL(f);try{const image=new Image();image.src=url;await image.decode();if(image.width*image.height>60000000)throw Error();items.push({name:f.name,url,image,delay:bounded('delay',.02,60)});added++;if(items.length===1){const w=Math.min(640,image.width);$('width').value=w;$('height').value=Math.round(w*image.height/image.width);ratio='original'}}catch{URL.revokeObjectURL(url);toast('图片无法读取或尺寸过大：'+f.name)}}if(added){record();renderFrames();update()}}else{const f=list[0];if(!f)return;const url=URL.createObjectURL(f);const v=$('video');try{await new Promise((resolve,reject)=>{v.onloadedmetadata=resolve;v.onerror=reject;v.src=url});if(!Number.isFinite(v.duration)||!v.videoWidth)throw Error();if(videoURL)URL.revokeObjectURL(videoURL);videoURL=url;vidDuration=v.duration;$('start').value=0;$('end').value=Math.min(5,vidDuration).toFixed(2);$('start').max=vidDuration;$('end').max=vidDuration;$('scrub').max=vidDuration;$('videoDuration').textContent=`全长 ${vidDuration.toFixed(1)} 秒`;$('width').value=Math.min(640,v.videoWidth);$('height').value=Math.round(num('width')*v.videoHeight/v.videoWidth);ratio='original';await seek(0);record();update()}catch{URL.revokeObjectURL(url);vidDuration=0;v.removeAttribute('src');update();toast('此视频无法解码，请尝试 H.264 编码的 MP4 视频。')}}}
$('fileInput').onchange=e=>{loadFiles(e.target.files);e.target.value=''};const drop=$('dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover')};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');loadFiles(e.dataTransfer.files)};
for(const id of ids){$(id).addEventListener('change',()=>{if(id==='width'||id==='height'){const prev=Number(last.values.width)/Number(last.values.height);if($('lock').checked){if(id==='width')$('height').value=Math.round(num('width')/prev);else $('width').value=Math.round(num('height')*prev)}$('width').value=bounded('width',16,1920);$('height').value=bounded('height',16,1920);if(!$('lock').checked)ratio='custom'}if(id==='start'||id==='end'){if(vidDuration){$('start').value=Math.max(0,Math.min(num('start'),vidDuration-.02));$('end').value=Math.max(num('start')+.02,Math.min(num('end'),vidDuration));seek(num('start')).then(draw)}}if(id==='fit'&&$('fit').value==='stretch')toast('拉伸填充可能使画面变形');stop();record();update()});if($(id).type==='range')$(id).addEventListener('input',draw)}
document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{ratio=b.dataset.ratio;if(ratio==='custom'){$('lock').checked=false;$('width').focus()}else{let r=Number(ratio);if(ratio==='original'){const src=mode==='image'?items[0]?.image:$('video');r=src?(src.naturalWidth||src.videoWidth)/(src.naturalHeight||src.videoHeight):1;if(!r)r=1}$('height').value=Math.max(16,Math.min(1920,Math.round(num('width')/r)));$('lock').checked=true}record();update()});document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{quality=b.dataset.quality;record();update()});
$('applyDelay').onclick=()=>{items.forEach(x=>x.delay=bounded('delay',.02,60));record();renderFrames();update();toast('已应用到全部图片')};$('distribute').onclick=()=>{if(!items.length)return toast('请先添加图片');const answer=prompt('请输入图片序列总时长（秒，不含首尾额外停留）：',String(items.length));if(answer===null)return;const n=Number(answer);if(!(n>=items.length*.02&&n<=items.length*60))return toast('请输入有效时长，每张应为 0.02 至 60 秒');items.forEach(x=>x.delay=Math.round(n/items.length*100)/100);record();renderFrames();update()};$('reverse').onclick=()=>{items.reverse();selected=0;record();renderFrames();update()};$('reset').onclick=()=>{if(!confirm('重置全部编辑设置？已添加的素材会保留。'))return;const defaults={width:640,height:640,lock:true,fit:'contain',delay:1,speed:1,fps:15,loop:0,loopCount:3,direction:'forward',target:0,bg:'#ffffff',transparent:false,zoom:1,posX:50,posY:50,rotation:0,flip:'none',firstHold:0,lastHold:0,filename:'我的动图'};for(const [id,v]of Object.entries(defaults))$(id)[$(id).type==='checkbox'?'checked':'value']=v;items.forEach(x=>x.delay=1);ratio='original';quality='256';const src=mode==='image'?items[0]?.image:$('video');const r=src?(src.naturalWidth||src.videoWidth)/(src.naturalHeight||src.videoHeight):1;$('height').value=Math.round(640/(r||1));record();renderFrames();update()};
