$('scrub').oninput=async()=>{stop();if(vidDuration){await seek(num('scrub'));draw()}};
$('play').onclick=()=>{if(playing)return stop();playing=true;playStart=performance.now();$('play').textContent='Ⅱ';$('play').setAttribute('aria-label','暂停预览');if(mode==='video'){tickVideo()}else tickImages()};
